#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (6) ---
patchFile('siman_013/mechaber/part-001.txt', 'mechaber', {
  '1#main': `Animals that do not require shechitah. In it are 6 seifim. Behemah, chayah, and fowl require shechitah; fish and locusts do not require shechitah. {Rama: And it is permitted to eat them dead, or to cut off a limb from them and eat it; but it is forbidden to eat them alive because of bal teshaktzu (Hagahot Maimoniyot chapter 1, Hagahot Mordechai, Tosafot).}`,
  '2#main': `One who slaughters the animal and finds it kosher, and finds in it a fetus eight months old—whether alive or dead—or nine months dead: it is permitted in eating and does not require shechitah. And if he found in it a nine-month-old alive: if it spread its legs on the ground it requires shechitah; but other treifot do not forbid it (the mother). And if it did not spread on the ground—it does not require shechitah. And if its hooves are cloven (meaning: its hoof is entirely one and is not split) (or there was some other strange matter) (Hagahot Ashiri)—even though it spread on the ground it does not require shechitah. And some are uncertain in the matter.`,
  '3#main': `If he did not slaughter the mother but tore her open; and likewise if he slaughtered her and it became neveilah in his hand, or was found treifah: if the fetus (found in it) nine months alive requires shechitah for itself and is permitted through it (the mother). And if it is nine months dead or eight months—even alive—behold this is forbidden. {Rama: And now we do not permit any fetus found in an animal if the mother is treifah (Hagahot Maimoniyot in the name of Semag end of prohibitions 136, Orach Chaim end of kllal 55); and his own shechitah does not help, for we are concerned perhaps it is not nine months old.}`,
  '4#main': `A nine-month-old live fetus found in the intestines of a slaughtered kosher animal: if it grew and came upon a regular animal and engendered—that offspring has no remedy through shechitah. And if it came upon a daughter of ben pakuah like him—behold his son and son's son until the end of all generations are like him, and all require shechitah by rabbinic decree, and treifot do not disqualify them.`,
  '5#main': `One who slaughters the animal and finds in it the form of a fowl—even though it is a pure fowl—behold this is forbidden in eating. Only what is found in an animal that has a hoof was permitted. {Rama: And some say: even if its hooves are cloven, only that it resemble an animal of its species that has a hoof (see s.k. 20).}`,
  '6#main': `One who slaughters the animal and finds in it a creature that has two backs and two spines—it is forbidden.`,
});

// --- siftei-kohen (21) ---
patchFile('siman_013/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '2#א': `<b>Whether alive or dead.</b> For an eight-month-old alive is like dead, since it cannot live.`,
  '2#ב': `<b>Permitted in eating.</b> For it is written regarding behemah "its flesh you may eat," and Chazal expounded: all that is found in behemah you may eat; but its blood is forbidden like other blood, as in the Talmud and poskim—and so below siman 66; and the reason the Rosh and Ran wrote there; regarding its milk and gid see below siman 64 seif 2; regarding whether one may redeem with it see siman 321 seif 4.`,
  '2#ג': `<b>And does not require shechitah.</b> For it is permitted through its mother's shechitah; and this is proved in the mishnah: wherever it does not require shechitah there is no issue of oto v'et beno, and it is permitted to slaughter it on the day its father or mother was slaughtered—and so all the poskim.`,
  '2#ד': `<b>If it spread on the ground it requires shechitah.</b> By rabbinic decree, lest one come to confuse it with other kosher animals when they see one eating it without shechitah—as in the Talmud and poskim.`,
  '2#ה': `<b>But other treifot.</b> That is to say: other treifot that are not due to slaughter, which are not publicized so much—they do not forbid it; but treifot due to slaughter, such as shehiyah, derisah, chaladah, pressing, or slaughter with a flawed knife and the like—as if he did not slaughter at all; for since they required shechitah for it, it needs proper shechitah—so many times the Rosh, Ran, Rabeinu Chananel in Beit Yosef, and other poskim; and so Maharshal in chapter HaMakishah seif 10.`,
  '2#ו': `<b>Even though it spread on the ground, etc.</b> For since it is a strange matter, a voice goes out about this cloven hoof and they say "it is ben pakuah"; and through their wonder at its closure they remember all its matters and do not come to confuse it—Rashi and poskim.`,
  '2#ז': `<b>And some are uncertain in the matter.</b> That is to say: cloven hooves alone do not help when it spread on the ground until there are two wonders—that is, that its mother too should be cloven; and the Pri Toar wrote that some forbid until there are two wonders, such as a cloven son of a cloven ben pakuah, etc.—end of his words; and I do not know from where he derives this. And it appears he brought this from Rashi's words (and Beit Yosef brings it), who wrote on what the Gemara says where some say Abaye said: all agree regarding a cloven son of a cloven ben pakuah that it is permitted—and he explained: a cloven son of a cloven mother, and that cloven mother was pakuah, and this cloven one was found in her—end of his words; he understood that Rashi means that that cloven mother was also ben pakuah (and the Bach too went this way, as in s.k. 14 there). But one can answer: behold Rashi did not write "and that cloven mother was ben pakuah" but only "was pakuah"—meaning her abdomen burst and this cloven one was found in her; and "ben pakuah" that the Gemara says refers to this cloven one found in her—and that is the language of "son"; otherwise it should have said "daughter pakuah," whereas every ben pakuah in the world is called thus because he is the son of a pakuah—that is, his mother's abdomen burst and they found him in her. But plainly one need not require that his mother be a daughter pakuah; for by law even if it spread on the ground it is permitted, except because of marit ayin it is forbidden; therefore when there are two wonders—that it is cloven and a son of a cloven mother—what difference whether his mother is a daughter pakuah or not? In the end there are two wonders; and so is explicit in Rashba daf 76d and in Teshuvot HaRashba daf 58b as he explained, and so in the Ran and Rabeinu Yerucham and other poskim; and so Maharshal there on Rashi's words—and he explained: according to his explanation, not that his mother was also a daughter pakuah, but meaning pakuah in whom a cloven offspring was found—end of his words; and this is plain.`,
  '3#א': `<b>Requires shechitah.</b> D'oraisa; and all other treifot disqualify it—so is plain in the Talmud and poskim; and see below siman 16 seif 9: regarding oto v'et beno there is a distinction between one who slaughters and it becomes neveilah versus one found treifah; and regarding kisuy hadam in siman 28 seif 17 there is no distinction as here; and see in the Talmud chapter Kol HaBasar (daf 88).`,
  '3#ב': `<b>Behold this is forbidden.</b> For its mother's shechitah did not avail to purify it, and it needs shechitah; and since it is nine months dead or eight months alive—which is considered like dead—shechitah does not help for it, and it is forbidden.`,
  '3#ג': `<b>If the mother is treifah.</b> But if she is kosher it is kosher—even nowadays; for even if it is eight months old, its mother's shechitah purifies it; and so too where its mother too did not require shechitah—it is plain that even if the mother was found treifah the fetus does not require shechitah and is kosher even nowadays.`,
  '3#ד': `<b>For we are concerned perhaps it is not nine months old.</b> But surely when one waits until the beginning of the eighth month from its birth—then it emerges from doubt of miscarriage; and as below siman 15—even if its mother was treifah it is permitted through its own shechitah; and so too in Perishah seif 12.`,
  '4#א': `<b>A nine-month-old, etc.—has no remedy through shechitah.</b> For behold it is like one who has only one siman from its mother's side—for the second siman is "slaughtered and standing," since shechitah does not apply to it; and a behemah with one siman is not koshered; and this latter siman cannot combine with the former, for you have no greater pause than this—that the first was slaughtered from when it was born (Rashi and poskim). And even though ben pakuah from a treifah is permitted through its own shechitah—here, since the father of the offspring is a proper ben pakuah and did not require shechitah, his simanim are as if slaughtered; if so, the offspring born from him has one siman as slaughtered—the Rashba, Ran, and they are brought in Beit Yosef, Tosafot, Rosh, Rabeinu Yerucham, and other poskim. And therefore the Mechaber was precise and wrote "found in the intestines of a slaughtered kosher animal."`,
  '4#ב': `<b>And it grew and came upon a regular animal, etc.</b> The same law applies in reverse—that is, a regular animal that came upon a daughter pakuah and engendered her: that offspring has no remedy, for the reason mentioned; and see below siman 14 s.k. 11 that the milk that comes from it is also forbidden.`,
  '4#ג': `<b>And engendered.</b> It appears for this reason the Taz and other poskim were precise and wrote "and engendered"—to exclude where it did not give birth but was only found in the mother: then it is permitted through its mother's shechitah and has no siman at all, for behold it is as slaughtered whether from its mother's side or its father's side, and is permitted like a general ben pakuah—and so the Bach; and so it appears from Rashi's language in s.k. 12. And the Bach wrote—and this is his language: it appears the same applies to a regular animal that came upon a daughter pakuah and the pakuah was slaughtered and an offspring was found in her—that offspring too is permitted through its mother's shechitah, as proved from Abaye's later language that deals with such a case; and we do not say: since its mother does not require shechitah by Torah law and the offspring requires shechitah, if we are concerned for the father's seed then it is not permitted through its mother's shechitah—but we say the expansion "all in behemah" includes everything: in any case where the mother is permitted in eating, the offspring too is permitted in eating through its mother if found inside her—end of his words. And one may question: Abaye's later language deals with one that is cloven ben pakuah—that is, found in the womb of a cloven mother, and that cloven mother is not a daughter pakuah but her abdomen burst and this cloven one was found in her, as in s.k. 7; but if an offspring is found in a daughter pakuah that became pregnant from a regular animal, one can say: since this daughter pakuah does not require shechitah, the offspring is not permitted through its mother's shechitah and is like a yelud—it has one siman from its father's side, and the second—which is from its mother—is likewise as slaughtered, and has no remedy; and we do not expand from "in behemah you may eat" except where it is permitted through its mother's shechitah; but here, since its mother does not require shechitah, it is as if not slaughtered—and the offspring is like a yelud that has no remedy.`,
  '4#ד': `<b>Behold his son and son's son, etc.</b> Meaning: even if they were born in the normal way of birth, only that their sons too will come upon offspring of their kind like them—that are pakuot or were born from pakuot—and so Maharshal there seif 9.`,
  '4#ה': `<b>Require shechitah by rabbinic decree.</b> Since they spread on the ground.`,
  '5#א': `<b>One who slaughters the animal, etc.</b> This is the Rambam's language; and Beit Yosef wrote: it appears from his words that we require an actual hoof in the eye, and it does not suffice that the species has a hoof; if so, when it has an actual hoof, even if it is a fowl it is permitted.`,
  '5#ב': `<b>And finds therein, etc.</b> All the more so if born in a fowl—forbidden; and as written in siman 79 there.`,
  '5#ג': `<b>Only what has a hoof was permitted.</b> For so it is written: "every one that parts the hoof," etc., "of the behemah you may eat"—and Chazal expounded thus.`,
  '5#ד': `<b>And some say even if its hooves are cloven, etc.</b> This is the view of Tosafot and the Rosh and their supporters, who hold the matter does not depend on hooves but on a species that has a hoof; only it is difficult against what the Rav wrote: even if its hooves are cloven, only that it resemble an animal, etc.—for in such a case certainly no one argues, and it is the Gemara in Arukh chapter HaMakishah: a closed cow in the womb of a cow is permitted; and the derashah was difficult for him too—that it should teach us that even if it has no hooves at all it is permitted; and he wrote—and this is his language: it appears to me that the Rama holds the Rambam does not require that the behemah found inside a behemah have hooves, but we require that one find in it a behemah of a species that has hooves; and even if it has no legs at all, or legs like a dove's, it is kosher since this species of behemah has hooves in its kosher state. And the Rama added: even if a camel is found inside it that has no hooves at all but only dove's legs, or has no legs—and its species too have no hooves in their kosher state—but its hooves are cloven, meaning like a donkey whose hooves are entirely cloven—nevertheless, since this camel is a species of behemah, he means to say that from the species that is included under the name behemah there are behemot that have a hoof in their kosher state that are kosher, unlike a fowl that does not have the name behemah—end of his words. And his words are strained; and further, if so it is already explained in the Rambam's words that everything depends on resemblance—so what need did the Rav have to add "some say" anything? And further, who are these "some say"? And in my humble opinion it is clear the Rav understood the Mechaber's words as the Mechaber himself intended, as in s.k. 17; and he refers to the end where it says only what is found in a behemah that has a hoof—meaning: when it has a hoof, even if it is the form of a fowl, it is permitted; and he says "some say" that it is not permitted even if its hooves are cloven when it is the form of a fowl (and that he did not teach us a stringency that it is not permitted even if it has two hooves when it is the form of a fowl—because one hoof or two are the same; and so one must say in Darkei Moshe, as I wrote in my hagahot to Darkei Moshe; or the language of the Mechaber was imprecise and implies it is permitted even with one hoof) only that it resemble a behemah of a species that has a hoof—meaning everything depends on resemblance and not on the hoof; and this is the view of Tosafot, Rosh, Rashba, Ran, R' Yerucham, Tur, and the Maggid, who hold everything depends on resemblance: if it has the form of a behemah, even if it has no hoof at all it is kosher since the species has a hoof; and if it is the form of a fowl, even if it has a hoof it is forbidden—and so Maharshal there seif 2.`,
  '6#_': `<b>Forbidden.</b> Because the Merciful One taught Moses regarding the split creature that it is forbidden; and likewise in its mother's womb He taught it is forbidden, for behold it cannot live even one hour when it goes out into the air of the world—Talmud.`,
});

// --- turei-zahav (10) ---
patchFile('siman_013/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#_': `<b>Fish and locusts.</b> Regarding fish it is written of them: "if you gather all the fish of the sea for them"—an ordinary gathering suffices; and this is written in a place where shechitah is mentioned regarding behemot. And locusts are equated to fish, for it is written "and to every living creature that swarms in the waters—these are fish; and to every creature that crawls on the land—these are locusts."`,
  '2#א': `<b>Permitted in eating.</b> For it is written "of the behemah you may eat," and we expound: all that is found in behemah you may eat—for its mother's shechitah permits it.`,
  '2#ב': `<b>And does not require shechitah.</b> This language is seemingly superfluous; and it appears it teaches us there is no prohibition of eiver min hachai, and it is permitted to eat it even if one cuts from it while it is still alive; and similarly we find in Rashi's explanation at the end of chapter R' Akiva, who wrote there is no prohibition of eiver min hachai since it does not require shechitah—only there is bal teshaktzu, etc.—end of his words. And here there is no bal teshaktzu, for one takes it while still alive and cooks it; for if there were a prohibition of eiver min hachai it would be forbidden once one cut it while alive. And in the Tur it is written here: and its blood is forbidden and its milk is permitted; and the Rosh wrote the reason: its blood is forbidden because it is absorbed throughout the body and is considered like the blood of the limbs of the behemah itself—end of his words. And one must explain his view: why should the milk too not be considered like the milk of the behemah itself? And it appears his view is that the blood in the fetus mixes with the blood of the behemah itself, since the fetus was formed and nourished from it—therefore it is not better than the blood of the behemah itself.`,
  '2#ג': `<b>Requires shechitah.</b> Because of marit ayin, lest one confuse it with a complete behemah, since this one too spread on the ground. And one should consider what its law is b'dieved if it was not slaughtered: if we are so stringent because of the decree lest one confuse it—for from the Tur's language, who wrote "and all matters that disqualify in shechitah disqualify in it," it implies even b'dieved; or perhaps l'chatchila they said it disqualifies, as Tosafot wrote at the beginning of HaShochet in that of R' Yehudah who disqualifies until he slaughters the hind legs—and so it appears from that the Gemara permits R' Shimon ben Shezuri even l'chatchila without shechitah; and one need not extend their dispute so much. And there is further proof at the beginning of Gittin: we also find concern for confusion regarding one who brings a get from a country overseas—that it must be "written in my presence and signed in my presence," whereas by law "signed in my presence" alone should suffice; only because of confusion with other validation of documents. And we find there at the beginning of chapter 2 of Gittin that the tanna taught in the extra coming—that it teaches us that even b'dieved it disqualifies if he did not say both, meaning "written in my presence and signed in my presence." From which we learn: without the extra coming we would not disqualify b'dieved, for he did not say both—even though there is concern for confusion. If so, here where we do not find explicit disqualification b'dieved, we have no basis to be stringent to forbid b'dieved. And further: behold Beit Yosef wrote in the name of the Maggid and the great teachers that a flawed knife does not forbid at all, as above.`,
  '2#ד': `<b>Other treifot.</b> For they are not publicized so much; but regarding shechitah, since they required shechitah for it, we require proper shechitah—so too the Rosh.`,
  '2#ה': `<b>Its hooves are cloven.</b> For it is a strange matter and people mention that this wonder is ben pakuah and one will not confuse it. And some are uncertain: he holds like the other language in the Gemara that specifically two strange matters are required—that is, that it was pakuah and it is cloven, that it was slaughtered and an offspring was found in it that is also cloven; and b'dieved it is plain it does not forbid.`,
  '3#א': `<b>And likewise if he slaughtered her, etc.</b> In the Tur he wrote: even if he slaughtered her, etc.; and his intent is not to exclude—for since the beginning of the shechitah was proper it helps; and so regarding treifah—there is nevertheless proper shechitah that helps to purify it from neveilah; and Beit Yosef explained in the language of "even" that it is attached to the end, and there is no need for this.`,
  '3#ב': `<b>A nine-month-old alive, etc.</b> For we say in the Gemara: four simanim the Merciful One koshered in the verse "of the behemah you may eat"—that if one wishes he eats it through its mother's shechitah; and if its mother is treifah he slaughters for that nine-month-old alive that is permitted, either through two simanim of its mother or through its own; and therefore if it is nine months dead or eight months alive—for it has no shechitah of its own and its mother's shechitah too does not help it, since the mother was found treifah—it is forbidden.`,
  '4#_': `<b>That offspring has no remedy, etc.</b> Meaning: since that offspring was born from a regular animal and has no permission through its mother's shechitah—for behold its mother was not yet slaughtered—it needs its own shechitah by itself; and it itself was already half slaughtered—that is, from its father's side, who was ben pakuah—and half from its mother's side still needs shechitah; and when you slaughter it now there will be shehiyah between its half and its half. And the same applies if the father is a regular animal and the mother a daughter pakuah and engendered: the offspring has no remedy—and so Maharshal. But if that offspring was not yet born but after its mother was slaughtered it is found inside her—even though it spread afterward, nevertheless it was already permitted through its mother's shechitah; only afterward it needs shechitah because of marit ayin as above. And so if the father is a regular animal and the mother a daughter pakuah and she was slaughtered and an offspring is found inside her—the offspring is permitted, for the offspring never entered the category of its own shechitah at all; it was permitted in its mother's womb through "of the behemah you may eat," and even though afterward it spread, it does not require shechitah by Torah law—and this is that of "cloven son of a cloven mother" that I mentioned regarding "and some are uncertain" in seif 2. And it appears: since that offspring has no remedy, its milk too is forbidden—and I wrote from this in siman 14 seif 5.`,
  '5#_': `<b>What has a hoof.</b> For it is written "every one that parts the hoof," "of the behemah you may eat"—the matter depends on the hoof, and it does not suffice that the species of behemah has hooves—this is the Rambam's view. And "some say" is the view of Tosafot and the Rosh: even if it has no hoof at all, if that species has hooves it suffices.`,
});

// --- baer-heitev (14) ---
patchFile('siman_013/baer-heitev/part-001.txt', 'baer-heitev', {
  '2#א': `<b>In eating.</b> For an eight-month-old alive cannot live and is like dead. And the Shach wrote: but its blood is forbidden like other blood, as in siman 66; and regarding its milk and gid see below siman 64 seif 2; and regarding whether one may redeem with it see siman 321 seif 4.`,
  '2#ב': `<b>Shechitah.</b> And the Taz wrote: likewise there is no prohibition of eiver min hachai; and likewise no issue of oto v'et beno; and it is permitted to slaughter it on the day its father or mother was slaughtered.`,
  '2#ג': `<b>Shechitah.</b> And the Taz wrote: this shechitah is by rabbinic decree, lest one confuse it with other behemot; however b'dieved we need not be stringent, and it requires study for practical law; and in Nekudot HaKesef he ruled to forbid even b'dieved.`,
  '2#ד': `<b>It (the mother).</b> And the Shach explained: such as other treifot that are not due to slaughter, which are not publicized so much—they do not forbid it; but treifot due to slaughter, such as shehiyah or derisah, etc.—are as if he did not slaughter at all; for since they required shechitah for it, it needs proper shechitah. However according to the Taz b'dieved one does not disqualify it.`,
  '2#ה': `<b>Shechitah.</b> And the reason: it is a strange matter and people mention that this wonder is ben pakuah and one will not confuse it.`,
  '2#ו': `<b>In the matter.</b> And the reason is in the Shach: cloven hooves alone do not help until there are two wonders—that its mother too was cloven; but plainly one need not require that its mother be cloven and a daughter pakuah—rather when she is cloven alone it suffices, and not like the Bach.`,
  '3#א': `<b>Through it.</b> And the Shach explained: this shechitah is d'oraisa, and all other treifot disqualify in it; and see below siman 16 seif 9: regarding oto v'et beno there is a distinction between slaughtering and it becomes neveilah versus found treifah; and regarding kisuy hadam in siman 28 seif 17 there is no distinction as here; and see in the Talmud chapter Kol HaBasar daf 88.`,
  '3#ב': `<b>Treifah.</b> And the Shach wrote: but if she is kosher it is kosher—even nowadays; and so where its mother too did not require shechitah—even if the mother was found treifah the fetus does not require shechitah and is kosher even nowadays.`,
  '3#ג': `<b>Nine months.</b> And the Shach wrote: but surely when one waits until the beginning of the eighth month from its birth—then it emerges from doubt of miscarriage; as below siman 15—it is permitted through its own shechitah.`,
  '4#א': `<b>Through shechitah.</b> And the reason is in the Shach: because behold it is like one who has only one siman from its mother's side—for the second siman is slaughtered and standing, since shechitah does not apply to it by Torah law; and you have no greater pause than this—that the first was slaughtered from birth. And even though ben pakuah from a treifah is permitted through its own shechitah if it is nine months old—for we say in the Gemara "four simanim the Merciful One koshered" [or through two of its simanim] or through two simanim of its mother; and if its mother is treifah it can be koshered through two of its own—here it is not so, for its father's siman is as if already slaughtered; and therefore if ben pakuah from a treifah came upon a regular animal, the offspring is like other regular animals—see above siman 14 that the milk too from ben pakuah that came upon a regular animal is forbidden—end of his words. And the Taz wrote: the same applies if the father is a regular animal and the mother a daughter pakuah and engendered—that offspring too has no remedy—end of his words. However, a regular animal that came upon a daughter pakuah and the pakuah was slaughtered and an offspring was found in her—the Bach wrote it is permitted without shechitah; and the Shach wrote it has no remedy—and practical law requires study.`,
  '4#ב': `<b>From their words.</b> Meaning: if they spread on the ground.`,
  '4#ג': `<b>In them.</b> And the Shach wrote in the name of Maharshal: even if they were born in the normal way of birth, only that their sons too will come upon offspring of their kind like them—that are pakuot or born from pakuot.`,
  '5#_': `<b>Hoof.</b> And the Shach explained: everything depends on the form of a behemah: if it has the form of a behemah, even if it has no hooves at all it is kosher; and if it is the form of a fowl, even if it has two hooves like a behemah—even so it is treifah. But this hagahah is astonishing—for behold in seif 2 it is written that cloven hooves are more significant: even if it spread on the ground—see there.`,
  '6#_': `<b>And two.</b> The Merciful One taught Moses regarding the split creature that it is forbidden; and this is a creature that has two spines and two backs; and therefore in its mother's womb it is taught forbidden, for behold it cannot live—Gemara.`,
});

// --- beer-hagolah (6) ---
patchFile('siman_013/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Explicit in the Torah.`,
  '2#_': `Baraitot in Chullin daf 26 and 27.`,
  '3#_': `For behold after "the fish of the sea" Scripture mentioned them at the end of the order of Shemini—Rashi in the name of BaHalachot Gedolot there daf 66; the Rambam and Rashba have other derivations—see Beit Yosef.`,
  '4#_': `Mishnah there daf 74.`,
  '5#_': `There in the mishnah, and as Rav Kahana explains there daf 75.`,
  '6#_': `From the incident of Chama bar Abahu there.`,
});

// --- beur-hagra (13) ---
patchFile('siman_013/beur-hagra/part-001.txt', 'beur-hagra', {
  '1#א': `<b>Chayah and fowl, etc.</b> Chapter 2, R' Yehoshua in the name of R' Yishmael, chapter 2, etc., until "two years" regarding behemah.`,
  '1#ב': `<b>Fish.</b> There and in chapter 5 of Keritut.`,
  '1#ג': `<b>And locusts.</b> Keritut there and chapter 2 of Avodah Zarah: the Sages taught "locusts," etc., there 35a; a gentile who kindled, etc.; and chapter 9 of Shabbat.`,
  '1#ד': `<b>And it is permitted, etc.</b> Tosefta chapter 9 of Terumot: a person may eat fish and locusts whether alive or dead and need not be concerned.`,
  '1#ה': `<b>But forbidden, etc.</b> Gemara chapter 9 of Shabbat; and Tosafot there s.v. delo; and Tosafot Avodah Zarah 38a s.v. le'olam.`,
  '2#א': `<b>(Seif 2) But other, etc.</b> And Tosafot there s.v. denafal, etc.`,
  '2#ב': `<b>(Likkut) And some are uncertain in the matter.</b> Because we hold everywhere like the later language; but in Teshuvot HaRashba he wrote that most books do not have the later language at all; and even for books that have the text "the halachah is like the earlier language"—in rabbinic matters we follow the lenient view, and especially here where it is only because of marit ayin—and the Razah does not have "some say" but only "Abaye said," etc.; and he explains that the two languages do not argue: the earlier language says "all agree," meaning the rabbis of R' Shimon ben Shezuri; and the later language refers to the son of ben pakuah—for R' Yochanan who says R' Shimon ben Shezuri agrees regarding his son that it is forbidden; but if the son of ben pakuah is cloven and his son too is cloven, the son too is permitted; but regarding ben pakuah itself, according to the later view it is permitted through one—that it is cloven; and such was the text in books before Rashi, that Rashi wrote "thus some say Abaye," etc.—before him it was not written "some say" (end of his words).`,
  '3#א': `<b>(Seif 3) And it became neveilah, etc.</b> All the more so from treifah—for neveilah is like tearing, as written in chapter 5 (chapter 1 seif 2) and chapter 6 (chapter 5 seif 1) there.`,
  '3#ב': `<b>And if it is, etc.</b> As written there according to the view of those who permit—it forbids; and here we do not need "four simanim," etc.`,
  '4#_': `<b>(Seif 4) And if it came, etc.</b> As written above; and so was the text of Rashash, etc.; and all the more so according to the rabbis—for even R' Yochanan, who says "and his son is forbidden," refers only to its milk according to Rashash; and as written, Ze'iri said to him, etc.; and even R' Yochanan does not argue, etc.`,
  '5#א': `<b>(Seif 5) And some say, etc.</b> Therefore he cited the form of a dove—for everything depends on the form of a species that has a hoof; and Tosafot there s.v. almah, etc.; and in Yerushalmi chapter 8 of Terumot: one who slaughters a behemah and finds in it a pig—it is permitted in eating; a dove—forbidden in eating, as it says "behemah—in behemah you may eat," and not fowl in behemah.`,
  '5#ב': `<b>Even if its hooves, etc.</b> Not precise—for regarding this there is no one who argues; it is the Gemara in Arukh there; "if so, closed," etc.—behold the tanna taught, etc., "hoof," etc.; and so there 68b: "two hooves you may eat," etc., "one," etc.; and this is what the Rambam and Shulchan Aruch mean: "what has a hoof"—and Tosafot did not add except that even if it has no hoof at all—end of his words.`,
  '5#ג': `<b>(Likkut) Precise, etc.</b> For they raised a dilemma in Niddah 23b: if the form of a person was found and it was not resolved—and for stringency. Teshuvot HaRashba (end of his words).`,
});

// --- kereti (24) ---
patchFile('siman_013/kereti/part-001.txt', 'kereti', {
  '1#_': `Fish and locusts—for it is written regarding fish "if you gather all the fish of the sea," and regarding locusts it is written "gather the locust"; and the language of gathering implies without shechitah—see Peleti.`,
  '2#א': `Permitted in eating—for its mother's shechitah permits it; as written "all that is in behemah you may eat"—to include the fetus such as this.`,
  '2#ב': `And if it spread, etc.—sometimes it implies standing, and sometimes halachah; and one should be stringent regarding standing alone.`,
  '2#ג': `Requires shechitah—the meaning of all poskim, not like the Taz that shechitah is indispensable b'dieved; and therefore the Rashba requires a blessing on shechitah—for it does not suffice without it.`,
  '2#ד': `Shechitah—and one needs a blessing, for it is a rabbinic mitzvah—see Peleti.`,
  '2#ה': `But other treifot—and the Rashba's view: even if there was shehiyah and chaladah, etc., nevertheless it is permitted, for it is not discernible to all and the Sages did not lack precision; and the poskim's view is to forbid—and so it is reasonable.`,
  '2#ו': `It does not forbid—and if the windpipe was perforated or the gullet severed—see Peleti, where I placed parallels from the Talmud that one need not forbid.`,
  '2#ז': `It forbids—even if born treifah from the womb and formed from the womb—nevertheless "all in behemah" permits it—see Hagahot HaRosh chapter HaBehemah HaMakishah.`,
  '2#ח': `Its hooves are cloven—if so, the offspring is cloven, its hooves attached, found in its mother's womb—this too is not common; and since it is mentioned and people remember it, one will not confuse it—and it is permitted.`,
  '2#ט': `Or there was some other strange matter—this law is taken from Hagahot HaRosh, and there it says regarding it: a canopy is a strange matter and publicizing the matter—and it requires study.`,
  '2#י': `And some are uncertain—for he holds: always, even in a rabbinic matter, the halachah follows the later language, who holds we require another wonder—that is, the mother in whom the offspring was found should be cloven; and if so, it is "cloven son of cloven ben pakuah."`,
  '3#א': `Requires shechitah for itself—for "four simanim the Merciful One koshered"; and behold it is like a yelud and has shechitah.`,
  '3#ב': `And is permitted through it (the mother)—and if it has treifot it is forbidden like other behemot, for behold it is entirely like a yelud.`,
  '3#ג': `Behold this is forbidden—for it has no shechitah at all.`,
  '3#ד': `And now there is no permission, etc.—but if the mother is kosher, then for it—that the offspring is a complete miscarriage—its mother's shechitah permits it from "all in behemah you may eat."`,
  '3#ה': `For we are concerned perhaps it is not nine months old—and if it waited eight days from the beginning of its birth it is permitted—so wrote the Shach, Pri Chadash, and Perishah; and see Peleti where I extended in contradicting their words—and in any case it is forbidden even if it waited a long time.`,
  '4#א': `And it grew and came upon a behemah, etc.—the same applies to a regular behemah that came upon a behemah that was permitted through its mother's shechitah—as the Shach wrote.`,
  '4#ב': `That offspring, etc.—for on one side from ben pakuah the simanim are as slaughtered, and on the other side they are not as slaughtered; behold here there was either half a siman slaughtered and half not slaughtered; and even though we hold "four simanim the Merciful One koshered"—that is when its mother was treifah, for it has no simanim of its mother; then the Torah koshered its simanim; and then if it came upon a regular behemah, in truth the offspring is kosher. But if its mother was slaughtered afterward—it has no simanim, and behold they are as slaughtered, and there is no shechitah here; and therefore the Shulchan Aruch was precise: "found in its mother's intestines, slaughtered kosher." And know: all this is forbidden from doubt—for this is all if we are concerned for the father's seed; and we are uncertain whether we are concerned for the father's seed.`,
  '4#ג': `It has no remedy—and if it (the mother) came upon a regular behemah—see Peleti, where I wrote according to the Shach in siman 14 one may kosher it; and according to the Bach, even that offspring has no remedy.`,
  '4#ד': `And if she is a daughter pakuah and a regular behemah came upon her and she was slaughtered and that offspring was found in her—it too has no remedy, for the mother's shechitah cannot permit it—for it is slaughtered and standing; and the offspring has a bit of a siman from the male—that it is a regular behemah—Shach.`,
  '4#ה': `From their words—if they spread on the ground.`,
  '5#א': `And finds therein—all the more if born—it is also forbidden.`,
  '5#ב': `Even if its hooves, etc.—already explained above in seif 2 that on the contrary, if its hooves are found cloven, even rabbinically it does not require shechitah; if so, one must understand what "even" means—and the Acharonim extended, and what appears close to the simple sense: certainly if a kosher behemah is found in the womb of a behemah, even if its hooves are cloven, nevertheless it is kosher—only if the form is of an impure behemah and its hoof cloven is found in a behemah, then even though we hold in tractate Bekhorot "a camel born from a cow is kosher"—that is only to kosher it; but that the mother's shechitah should permit it—no; for it is the form of an impure animal and it has no hooves; and Scripture says "hoof"—to teach that nevertheless it is kosher since it is the form of a behemah, and the boundary of behemah is that it should have hooves.`,
  '6#_': `Forbidden—for it is written in the Torah regarding the split creature that has two backs and two spines, and it is not in reality that it could live even a short time; and the Torah only mentioned it if found in the womb of a behemah—a fetus that has this, so that the mother's shechitah should not permit it—and it is forbidden. Gemara—and that which they permit a dissolved placenta through the mother's shechitah and we are not concerned perhaps it is split and dissolved, or the form of a dove and shechitah does not permit—one must say: since it is not common, they were not concerned for this.`,
});

// --- peleti (6) ---
patchFile('siman_013/peleti/part-001.txt', 'peleti', {
  '1#_': `Fish and locusts do not require shechitah—in the Gemara at the beginning of chapter 2 of Chullin he derives: as written "the flock and cattle you shall slaughter for them," and "all the fish of the sea you shall gather"—from which we learn an ordinary gathering suffices. And the Gemara challenges: if so, since it is written "and they gathered the quail," etc., and the Gemara answers: it is written "gathering" in a place of shechitah. And the Rambam brought this in chapter 1 of Hilchot Shechitah; and regarding locusts he wrote: as written "as one gathers the locust." And the Rashba wondered in Teshuvot HaRashba: behold it is not written in a place of shechitah. And this is fifty years ago when I was here in the house of my father-in-law, my grandfather the famous philanthropist, beloved of the rabbis, such as R' Mordechai Cohen z"l—I said they should return to the simple way, for certainly the language of "gathering" indicates ordinary gathering and not shechitah; only the Gemara's difficulty is thus: behold it is written "and they gathered the quail"—and this certainly requires shechitah—and therefore it is written the language of gathering: in the desert they truly did not slaughter but only stabbed ordinarily; if so, also from fish of the sea there is no proof, for then in the desert it was properly said "fish of the sea you shall gather," for shechitah was not practiced; and the Gemara answers: it is written in a place of shechitah—for it is written "flock and cattle you shall slaughter," and even they did not need shechitah; only the Torah spoke in the language that was practiced for their offerings and the like—shechitah; if so, also gathering of fish is certainly so, and not because of the heter of nechirah meat; and this is all in the desert. But in the time of the prophet, when nechirah meat was forbidden, and it is written "gather the locust"—with the language of gathering you cannot resolve shechitah; therefore they are permitted without shechitah. And many years later I heard it was said in the name of a great man like my view.`,
  '2#_': `Or to cut off a limb from them—the Pri Chadash wrote that so it implies from the Gemara too: "all that you are commanded regarding its blood, you are commanded regarding its limbs," etc. And one may be precise a bit: if so, behold the Gemara challenges: and for R' Yehudah why does he need a verse?—the prohibition of eiver min hachai applies to a gentile; and what is the difficulty—perhaps it comes to permit fish and locusts? Rather, in truth no verse is needed for all this—for in the beginning of chapter Kol HaBasar it is explained that fish flesh is not called flesh either in Torah language or in people's language—"only flesh with its soul, its blood you shall not eat" is written regarding behemah and cattle.`,
  '3#_': `Other treifot—and perforation of the windpipe or severance of the gullet: there is room to doubt whether this impedes the shechitah and shechitah is needed; however one may rely on the Rashba that even for chaladah and the like he permits—and the same here. And there is support for this from the Gemara of the bear that fell on it and R' Yehudah permitted slaughtering it—and from this we learn treifot do not disqualify it. And one must understand: in bear trampling there is concern for the simanim—perhaps he trampled the simanim and the minor portion fell—and it would be like perforation and severance, for we do not find he was commanded to check against the simanim—or it is kosher; and it is possible the Rashba derives that even if there was chaladah it is kosher, like perforation and windpipe.`,
  '4#_': `Shechitah—and the Rashba in a responsum wrote that one should bless as on every rabbinic mitzvah. And the Pri Chadash questioned from the Ran's explanation in "With what may we kindle": in a courtyard that has two entrances he kindles in both—and the Ran wrote one does not bless, since there is only concern for suspicion—see there. And the case is not similar: there it is because of suspicion, and here because of marit ayin—and who compares this to that? Also there the explanation is not to bless at two entrances but at one entrance and exempt the other—for since it is because of suspicion, these two entrances are related to each other as one, and he considers and blesses on one and exempts the other. But here to exempt it entirely from a blessing while he fulfills this rabbinic mitzvah—we have not heard. And there is support for the Rashba's words from the Gemara in that which R' Ashi said to that one on whom a bear fell: slaughter it; and the Gemara challenges: behold the halachah is like R' Shimon ben Shezuri, who says shechitah is not needed. And one must understand: since it was trampled and would have died had it not taken its soul, as Rashi wrote—therefore in any case one must kill it; if so, what harm if he kills it by choking and nechirah or slaughters it—is it not better for it to have shechitah to fulfill the rabbinic matter they said: specifically shechitah where otherwise there is loss? And therefore he said to him simply "slaughter it"—meaning like other slaughtered animals, and he will bless; and if the halachah is like R' Shimon ben Shezuri that even rabbinically shechitah is not needed, there is no blessing here and it would be a blessing in vain—and examine.`,
  '5#_': `Any fetus found in a behemah, etc.—and the Shach wrote in s.k. 11: if one waits eight days it emerges from presumption of miscarriage—and so Perishah and Pri Chadash; and I am a disciple of our master and did not know—if so, what do the poskim Semag, Beit Yosef, and Orach Chaim teach us? Behold such is the law for all behemot: if we know its months are complete it is permitted; and this behemah too, if we know it completed its term it is permitted; and if we do not know—we are not expert to know this; all behemot are forbidden until it waited eight days; and when it waited—here too it is permitted; if so, what difference is there between this behemah and other behemot? And it appears the Rav author of Lechem Mishneh sensed this difficulty somewhat and wondered why we should forbid waiting eight days for it—and he wrote as I wrote; therefore it is clear those Geonim hold that which we rely on eight days—even though we do not know its months are complete—because a majority of behemot give birth to viable offspring, as Tosafot wrote explicitly in many places; and see Bekhorot. And therefore waiting helps—unlike here, where the behemah was not born and was in its mother's womb there is no majority here; and those Geonim hold that for this, waiting cannot be relied upon; and in Perishah it is explained because it was not resolved in Niddah daf 24 whether a behemah gives birth at seven months and waited—see there. And therefore they forbid—and this is clear and plain. And extending on this is unnecessary—and an error emerged before these rulers.`,
  '6#_': `It has no remedy—and if this offspring came upon a regular behemah and engendered—to the eye it appears that offspring too has no remedy—for here in this offspring there are some simanim as slaughtered; if so, also what is born from it has some simanim as slaughtered; and behold here there was shehiyah and the like. But it appears it depends on the dispute of the Bach and Shach below siman 14 s.k. 11 whether milk from that offspring is permitted—for according to the Shach it is treifah—see there; if so, when it came upon a regular behemah the offspring is permitted, for it is "this and this cause" and permitted—as Tosafot wrote explicitly in chapter Eizehu Mekoman in the sugya of Shichla Kama: there is a difference between concern for the father's seed versus "this and this cause"—regarding concern for the father's seed everything is permitted and forbidden; in "this and this cause," one treifah and one permitted—see what Maharsha wrote in HaBehemah HaMakishah in the section "why be concerned for its seed"—see there. But according to the Bach, who koshered its milk and it is not treifah—if so, concern for the father's seed applies, and also the offspring has no remedy; and see what I wrote below in siman 14 on this. And one may challenge according to the Shach that the offspring is treifah and its milk forbidden—if so, why did the Gemara toil in Zevachim to find in what the mishnah teaches "treifah"—perhaps it deals with an offspring such as this that is called treifah, and in truth it became mixed and has no recognition? And see what I wrote on this below siman 57 at length—and examine.`,
});

// --- pitchei-teshuva (6) ---
patchFile('siman_013/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `<b>Eight months.</b> See She'elat Yaavetz part 1 siman 25, who wrote that all distinctions said regarding a large animal between eight months and nine months apply also to a small animal between four months and five months—for a small behemah gives birth at five months—see there.`,
  '2#_': `<b>Nine months dead.</b> See responsum Radbaz Chadashot siman 190: his view is specifically if found dead it is permitted in eating; but if it died after it went out into the air of the world—even though it did not spread on the ground—it is forbidden in eating. And he wrote that the Ravyah's view is to distinguish also regarding one that was torn: its mother's shechitah permits only what occurred inside it as treifot, but what occurred afterward—not. But I concede to him regarding dead but not regarding torn—see there.`,
  '3#_': `<b>Requires shechitah.</b> Av Beit Din; and see responsum Bashamayim Rosh siman 283, who wrote one does not bless on its shechitah—see there; and see Pri Megadim and Av Beit Din below siman 19 s.k. 1.`,
  '4#_': `<b>Does not require shechitah.</b> See Parshat Derachim on Derech HaAtarim derush 1, who wrote shechitah is not needed for it, but nechirah is nevertheless needed—for it is no worse than one that convulses—below siman 27—see there.`,
  '5#_': `<b>Some other strange matter.</b> See Hagahot Ashiri in Chullin chapter HaBehemah HaMakishah what he wrote there: a canopy is so, and people wonder like that of Abaye who said all agree regarding cloven ben pakuah that it is permitted, etc.—see there; and it requires study for practical law; and see what I wrote below siman 16 s.k. 4.`,
  '6#_': `<b>Nine months.</b> Av Beit Din in the name of the Shach; and see Turei Zahav who disagreed on this and wrote that even if it waited forty days in a person and eight in a behemah, still this is not clear that it is not a miscarriage; and see Dagul MeRevavah who disagreed with him and agreed to the Shach; and so in Levushei Serad he too disagrees with the Turei Zahav—see there.`,
});

// --- rabbi-akiva-eiger-yd (6) ---
patchFile('siman_013/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  '1#_': `(Siman 13, Taz s.k. 1) <b>And this is written in a place where shechitah is mentioned.</b> For from the language of gathering alone there is no proof—for it is also written "and they gathered the quail"—so it is in our sugya. And with this it is well resolved for me the difficulty of Tosafot Chullin daf 17a s.v. Ra'ak, etc.: "say—whence do we know they argue? Perhaps one said one thing and one said one thing and they do not argue"—see there, who left it in wonder. And in my humble opinion it is difficult at first glance how they derive that fish do not require shechitah from "if you gather all the fish of the sea"—for according to Ra'ak in the desert nechirah meat was permitted for them; if so, one could say therefore it is written "gathering," and now that nechirah meat was forbidden one could learn fish too require shechitah. But in truth it is not difficult at all—for in any case, since in "flock and cattle" it is written "you shall slaughter for them," even though nechirah would have sufficed, nevertheless it is called shechitah—for then nechirah in the simanim is like shechitah for us, as the poskim say: their nechirah is their shechitah. If so, since regarding fish it is written "gathering," therefore because even nechirah in the simanim is not needed; and since even nechirah is not needed, also for us shechitah is not needed. If so, this proof works well both for R' Yehudah and for Ra'ak: for R' Yehudah, who forbade them desire-meat and they had to dedicate and needed actual shechitah—the proof is as plain from "gathering" written regarding fish—for never was nechirah permitted for them; therefore because fish do not need shechitah. And for Ra'ak, who permitted nechirah—the proof works well too: nechirah of theirs is called shechitah language in flock and cattle; therefore regarding fish where "gathering" is written—because even nechirah is not needed. And since so, Tosafot's difficulty is resolved: if they do not argue, it would be difficult whence we know the rule that fish do not need shechitah—for there would be no proof from the verse; one could say flock and cattle, which had to be dedicated and needed actual shechitah—therefore "you shall slaughter" is written; but fish, which are not matters of offering, suffice with nechirah—therefore "you shall gather" is written; and there is no difference between fish and other living creatures; and for us, who forbade nechirah, fish too are forbidden—nevertheless they argue, and the proof goes well both for R' Yehudah and for Ra'ak—as above; and examine well.`,
  '2#_': `(Shach s.k. 2) <b>And the reason the Rosh and Ran wrote.</b> And in my humble opinion one can say: as written "all in behemah you may eat"—which implies everything without any remainder; it is proved that the chelev and gid of a fetus are permitted; but regarding blood, even if it stands in prohibitions, nevertheless one can uphold the language "all in behemah" by cooking all the blood of the fetus and it becomes "blood in its cooked form" that is permitted; and with this reason I resolve Tosafot Pesachim daf 22a s.v. veharei dam, which implies blood is not included in behemah, etc.—and that is what they said: when neveilah was permitted, etc., "to the stranger in your gates" implies the entire neveilah may be given to him; and it is proved everything is permitted for benefit—including chelev and gid; but there is no proof from this that blood was permitted for benefit—for even if forbidden for benefit one can cook it and give it to the ger. And it is also resolved what Tosafot strained in Chullin daf 36a s.v. s'da, etc.—even though the derashah is not resolved, etc.; and according to the above, for blood too a verse is needed to forbid eating even through cooking.`,
  '3#_': `(Seif 2) <b>If it spread on the ground it requires shechitah.</b> See Pri Chadash below (siman 61): regarding priestly gifts—for in the Tosefta of ben pakuah, since we do not read it as "from your slaughterers of sacrifice," it is exempt from gifts even if it spread—see there. And with this the Sages were not stringent to make it like another behemah—see there.`,
  '4#_': `(There) <b>Requires shechitah.</b> And regarding the blessing, the Turei Zahav brought Rashba's responsum that one blesses; however in responsum Bashamayim Rosh siman 283 he wrote one should not bless.`,
  '5#_': `(There) <b>But other treifot do not forbid it.</b> I am uncertain regarding perforation of the windpipe: if we judge that since the essence of the shechitah was according to law with a checked knife without shehiyah, derisah, and chaladah—it is like other treifot that do not forbid; or since we hold perforation of the windpipe is neveilah and its disqualification is in the shechitah as if it was not slaughtered. And at first glance one may challenge from the Rif's omission of R' Zeira's statement, who whitened the knife and slaughtered with it because we do not hold "spacious opening"—spacious opening is wide; but nevertheless there is a practical difference to establish the explanation that sharpening precedes whitening regarding ben pakuah that spread on the ground and slaughtered with a whitened knife: if we do not say sharpening precedes whitening, it is only burning of the simanim and as if not slaughtered; but if sharpening precedes whitening, then even though there is no spacious opening and there is perforation of the windpipe before completion of shechitah—which would be kosher here—nevertheless this too is not proper shechitah and it is disqualified in the shechitah. However, according to what the Turei Zahav wrote above (siman 9) that even in a fowl, if one grasped the windpipe alone and slaughtered with a whitened knife it is disqualified since it is not spacious—for the burning causes disqualification even where sharpening precedes whitening—and he proved this from the Rif's omission of R' Zeira—there is a practical difference in a fowl; see there. If so, one can say therefore ben pakuah too is disqualified—for the simanim are burned; and nevertheless this does not suffice—for this explanation and the touch of the sides still does not require sharpening precedes whitening from reasoning—for if so, how did the Rishonim prove from the Talmud's challenge, "and there are sides where the windpipe was perforated in the place slaughtered before the majority was slaughtered"—it is disqualified; one can say the Talmud's challenge and "there are sides" mean: because of this we do not say sharpening precedes whitening; nevertheless according to the change in "spacious opening," one can say for practical law that perhaps without spacious opening we do not say sharpening precedes whitening; if so, nothing emerges from uncertainty; and regarding ben pakuah, whose shechitah is because of marit ayin, one can judge it is a rabbinic doubt—perhaps even though there are sides, we say sharpening precedes whitening; therefore also because of perforation of the windpipe the shechitah is disqualified as if not slaughtered. See further.`,
  '6#_': `(Seif 3 in hagahah) <b>For we are concerned perhaps it is not nine months old.</b> And if a flawed knife is found after shechitah—according to what I wrote above in siman 1, Taz s.k. 6: even though we hold like R' Chisda that without breaking a bone it is forbidden, nevertheless one can say it is only a doubt and is not comparable to a mikveh—see there. If so, one can say the offspring is permitted through its own shechitah through double doubt: perhaps the bone at the joint was damaged; and if you say in the hide it was damaged—perhaps its months were complete and its own shechitah helps. And nevertheless one can say there is double doubt against a presumption of prohibition, for it is not slaughtered; and even though we forbade the mother and did not establish the knife in its presumption—that now it was damaged—even though there is double doubt that perhaps he did not slaughter at the place of the flaw, this is because of presumption of prohibition that it is not slaughtered, as I wrote; and the first doubt is like certainty and the second doubt is doubt of prohibition; if so, besides the first doubt there is double doubt that perhaps he did not slaughter at the place of the flaw, and perhaps the offspring is a nine-month-old alive—nevertheless one can say that although if there were three doubts in a behemah it would help according to the Shach (siman 110) that one doubt is like certainty and again there is double doubt—for when we combine presumption of prohibition to make the first doubt like certainty, again there is double doubt without presumption of prohibition; but here, in its doubt of nine months, there is presumption of prohibition that the offspring is not slaughtered. And it is possible it depends on what we wrote elsewhere: in double doubt regarding one doubt there is presumption of prohibition, and regarding one doubt there is not presumption of prohibition—one can say it helps; if so, here the doubt that perhaps it is nine months—in this there is presumption of prohibition of the offspring; but the doubt that perhaps he did not slaughter at the place of the flaw—since on this side we judge that the offspring is eight months and is an offspring, and the behemah and offspring are one: if he slaughtered at the place of the flaw, both the behemah and offspring are forbidden; if not, both are permitted; and regarding presumption of prohibition of the behemah we already combined the first doubt that perhaps in the hide it was damaged to make it like certainty—and practical law requires study.`,
});

// --- nekudot-hakesef (3) ---
patchFile('siman_013/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `<b>(Siman 13 s.k. 3) This language is superfluous, etc.</b> I needed to say: what does "permitted in eating" teach—through shechitah? Or perhaps other treifot do not forbid it, but nevertheless it requires shechitah like at the end—the verse teaches us.`,
  '2#_': `<b>(s.k. 4) And one should consider, etc.</b> And in my humble opinion even b'dieved it is forbidden—for so is explicit to the Rosh, Ran, and other poskim, and Beit Yosef brings them; and so it appears from the Tur and Mechaber, who wrote regarding other treifot "do not forbid"—from which we infer shechitah forbids it even b'dieved; and the proofs he brought from ma'alin and gittin are not proofs at all—and examine.`,
  '3#_': `<b>(s.k. 6) And some are uncertain, etc.</b> Meaning: that it was pakuah, etc.—here he followed the Pri Toar and erred in this, as the Shach wrote in s.k. 7; and I showed this matter in Lublin at the German fair the Taz for the first chapter before several rabbis of the generation, and the matter reached him and he wanted to correct this on a page he printed at the end of his work, where he wrote—and this is his language: but afterward I saw in Maharshal's words that this is not needed, only the son alone, son of ben pakuah, etc.—and these words are astonishing: why need he see Maharshal's words? Whoever has a heart to understand will see the commentator errs in the opposite direction; also it did not help at all—for in any case he did not say in letter tet, meaning that of "cloven son of cloven mother" that I mentioned regarding "and some are uncertain" in seif 2—end of his words—he followed the Bach here to bring proof for his law, as the Shach wrote in s.k. 14; and these words are not corrected, as the Shach wrote there; and therefore one must also retract from this and say this is not proof.`,
});

// --- kaf-hachayim (6) ---
patchFile('siman_013/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `<b>(a) [Seif 1] Behemah, chayah, and fowl require shechitah.</b> Explicit in the Torah (Deuteronomy 12:21): "and you shall slaughter of your cattle and flock"; and chayah is derived in the first chapter of HaShochet (Chullin 27a) from what is written regarding disqualified consecrated animals: "only as the gazelle and deer are eaten," etc.—the gazelle and deer are compared to disqualified consecrated animals: just as disqualified consecrated animals require shechitah, so gazelle and deer require shechitah. And fowl is derived from what is written: "whoever hunts and traps animal or fowl and pours out its blood"—teaching that pouring the blood of fowl is like pouring the blood of chayah. Beit Yosef. Levush. And see further above siman 1, section 1.`,
  '2#_': `<b>(b) There. Fish and locusts do not require shechitah.</b> Regarding fish it is written of them: "if you gather all the fish of the sea for them"—an ordinary gathering suffices; and this is written in a place where shechitah is mentioned regarding behemot. And locusts are equated to fish, as written "and to every living creature that swarms in the waters—these are fish; and to every creature that crawls on the land—these are locusts." Taz s.k. 1. And these are the words of Beit Yosef—see there.`,
  '3#_': `<b>(c) There, hagahah. And it is permitted to eat them dead.</b> And even if they died inside the water. Kaneh in Hagahat Beit Yosef section 8, Shulchan Gavoah section 1, Zivchei Tzedek section 3; and see there what he wrote to attack Maharshadam's words—see there. And so Zivchei Tzedek section 1—for such is primary, and not like Maharshadam—see there.`,
  '4#_': `<b>(d) There in hagahah. Or to cut off a limb from them and eat it.</b> And we would say they are not forbidden because of eiver min hachai—such as cutting a limb and rinsing it well and eating it, for there is no bal teshaktzu in it. Pri Chadash section 1, Shulchan Aruch HaRav section 1, Zivchei Tzedek section 5; and one need not wait until the fish or locust dies from which this limb was taken, as required for a slaughtered behemah—as below siman 27—for they do not have so much life as something that requires shechitah. Shulchan Aruch HaRav there. Mishnat Hasidim section 3, Beit Av section 17 section 3. But one must wait until the limb dies. Minchat Yosef section 1.`,
  '5#_': `<b>(e) And one should not</b> pass a live locust before one's mouth because of marit ayin, lest they say he eats it and transgresses bal teshaktzu; and the same applies to a live fish—from the Taz. Shulchan Aruch HaRav there. Minchat Yitzchak there. And see below siman 85 sections 7 and 8.`,
  '6#_': `<b>(f) [Seif 2] One who slaughters the animal, etc.</b> And chayah is included in behemah. Shulchan Piskei Dinim section 2, Darkei Torah section 9; and see below section 53.`,
});

// --- yad-avraham (6) ---
patchFile('siman_013/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 13 seif 1) <b>Chayah and fowl require shechitah.</b> Maharam wrote: according to the view that melikah for a fowl is not from the Torah, it is not neveilah at all—for it is all one nechirah—unless it died by itself or he struck its head, then it is neveilah; but in such a case it is nechirah—and examine. And it is difficult: if so, why was a verse needed for "all their sin-offerings" to include the fowl sin-offering that is eaten—for one might have thought it is neveilah, as explained in Zevachim (daf 44)—and I found he sensed this in Be'er Yitzchak. And see further in Torat Kohanim chapter 6 Vayikra, where R' Shimon also derives from another verse to permit melikah of kohanim.`,
  '2#_': `(Seif 1 in hagahah) <b>And it is permitted to eat them dead, or to cut off a limb from them and eat it.</b> In Pri Toar he attacked what the Pri Chadash wrote: the reason regarding fish that a limb from a live animal is permitted is because we say in chapter 5 of Pesachim: "all that you are commanded regarding its blood, you are not commanded regarding its limbs." And this is not proof—for this derivation is only to include impure species that are forbidden; and whence do we know the verse also comes to teach us a leniency to permit a limb from a live fish? And it was hidden from him that in Sanhedrin (daf 59b) they derive to permit a limb from a live creeping thing from the verse of Noach—for their blood is not distinct from their flesh, that afterward it is because of blood. If so, all the more so fish, whose blood is entirely permitted. And what Pri Toar wrote: if we say the verse comes to permit fish—one could ask for R' Eliezer: perhaps for this it comes and not to forbid impure species—there is no question; for how can we say for leniency and not for stringency? And further, for leniency we learn from Noach's verse.`,
  '3#_': `(Shach s.k. 3) <b>For wherever it does not require shechitah there is no issue of oto v'et beno—therefore.</b> And exempt from gifts—for it is written "from your slaughterers of sacrifice"—Tosefta.`,
  '4#_': `<b>In Pri Megadim</b> he was uncertain whether it is permitted to extend a limb from a live ben pakuah to a gentile—for perhaps since it runs and goes, its blood ascends and one redeems with it—it is forbidden to a gentile. And see in Pesachim, where he is precise from R' Natan that it is forbidden to extend a limb from a live animal to a gentile because of lifnei iver—for otherwise it would be permitted for benefit; and if it were so that a limb from ben pakuah is forbidden to a gentile even though permitted to an Israelite, nothing would be proved. And so he wrote in his book Rosh Yosef. However, one can say: there he was precise that it is permitted for benefit from that which he said specifically to a gentile it is forbidden, but to dogs it is permitted—even to dogs of a gentile; and if it were forbidden for benefit, here too there would be lifnei iver, for he benefits the gentile and he too is forbidden to benefit—at least according to R' Meir, who reads "you shall not eat" as benefit. And on this basis the wonder of Tosafot there is resolved; and so it is not found in one that convulses.`,
  '5#_': `(Seif 4) <b>A nine-month-old alive, etc., and it grew and came upon a regular behemah and engendered—that offspring has no remedy through shechitah.</b> This is the statement of Rav Mesharshia in chapter HaMakishah (daf 75); and the Rif and Rambam omitted this. And Beit Yosef wrote: I do not know why; and in my humble opinion they explain like Rashi there—that Rav Mesharshia argues against Rav, who said "four simanim the Merciful One koshered"; for according to Rava, its own shechitah would help. And therefore, since they ruled like Rava, who is later, Rav Mesharshia's statement is rejected and we do not hold like him. And similarly in the Ran, siman 14. And behold the reason for this law is explained in the poskim—that is, because from the father's side it is already slaughtered, and from the mother's side it was not yet slaughtered; and it is as if in the midst of its shechitah—and therefore it has no remedy through shechitah. And it requires study: therefore regarding an offspring whose father and mother are both sons of cloven pakuot who do not require shechitah at all, and it is not cloven—for it requires shechitah by rabbinic decree—from one side, father or mother, it is already fully slaughtered, and from the other side it is not slaughtered rabbinically—whether its own shechitah helps. And one may be lenient here, since without this, according to Rashi, Rif, and Rambam, Rav Mesharshia's view does not exist—one may be lenient in such a case.`,
  '6#_': `(Shulchan Aruch) <b>And if it came upon a daughter pakuah like him—behold his son, etc., like him.</b> And it is proved in the Talmud, Rashi, and Tosafot at the beginning of chapter HaMakishah (daf 69a) that even a nine-month-old live ben pakuah that has a prohibition emerging in one limb—as written in the siman afterward: that it came upon a daughter pakuah like him that also has a prohibition emerging in one limb—for that limb has no remedy through shechitah, as explained in siman 14. Nevertheless, that offspring which it engendered has no prohibition in this limb—for its seed confounds—see there.`,
});

